// Built-in cycling workouts, written once from structured sources and then ours to edit. Steps are builder text.
// Names come from the mountain where a cirmolo grows: the harder the workout, the higher it lives. Recovery is the valley
// floor, endurance the forest, tempo and sweet spot the treeline; threshold is the animals above it, VO2max the birds,
// anaerobic what bursts, the Beasts what you don't mess with, warm-ups the flowers, because they open. The species fits the
// workout's shape, the same species means the same kind of work in any sport, and the number is the dose.
import type { Focus } from "./races";
import type { WorkoutKind } from "./workout-templates";

export type LibraryEntry = {
  id: string;
  kind: WorkoutKind;
  focus?: Focus;
  name: [string, string];
  about: [string, string];
  /** Builder text; {aero}, {up} and {cadence} are step labels, put in the reader's language. */
  steps: string;
  seconds: number;
};

